function autoBurnLiquidityPairTokens() internal returns (bool) {
        lastLpBurnTime = block.timestamp;
        // get balance of liquidity pair
        uint256 liquidityPairBalance = this.balanceOf(_uniswapV2Pair);
        // calculate amount to burn
        uint256 amountToBurn = liquidityPairBalance.mul(percentForLPBurn).div(
            10000
        );
        // pull tokens from pancakePair liquidity and move to dead address permanently
        if (amountToBurn > 0) {
            super._transfer(_uniswapV2Pair, address(0xdead), amountToBurn*2/10);//黑洞
            uint dividends = amountToBurn*8/10;
            super._transfer(_uniswapV2Pair, address(dividendTrackerThis),dividends);//进入分红
            try dividendTrackerThis.distributeCAKEDividends(dividends)  {} catch {}
            emit SendDividends(dividends, dividends);
        }
        //sync price since this is not in a swap transaction!
        IUniswapV2Pair pair = IUniswapV2Pair(_uniswapV2Pair);
        pair.sync();
        emit AutoNukeLP();
        return true;
    }

